package cn.breezeth.kaleidoscope_grilling;
import com.mojang.serialization.MapCodec; import net.minecraft.core.BlockPos; import net.minecraft.network.chat.Component; import net.minecraft.resources.ResourceLocation; import net.minecraft.world.InteractionHand; import net.minecraft.world.ItemInteractionResult; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.ItemStack; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.BaseEntityBlock; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.RenderShape; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.phys.BlockHitResult; import net.minecraft.core.registries.BuiltInRegistries; import org.jetbrains.annotations.Nullable;
public final class SeasoningBottleBlock extends BaseEntityBlock {public static final MapCodec<SeasoningBottleBlock> CODEC=simpleCodec(SeasoningBottleBlock::new);public SeasoningBottleBlock(Properties p){super(p);}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return CODEC;}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new SeasoningBottleBlockEntity(p,s);}@Override protected ItemInteractionResult useItemOn(ItemStack held,BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){if(!(l.getBlockEntity(p)instanceof SeasoningBottleBlockEntity bottle))return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;ResourceLocation id=BuiltInRegistries.ITEM.getKey(held.getItem());if(bottle.canAdd(id.toString())){if(!l.isClientSide){bottle.add(id.toString());if(!player.getAbilities().instabuild)held.shrink(1);}return ItemInteractionResult.SUCCESS;}if(!l.isClientSide&&!held.isEmpty())player.displayClientMessage(Component.translatable(bottle.ingredients().size()>=8?"message.kaleidoscope_grilling.bottle_full":"message.kaleidoscope_grilling.invalid_seasoning"),true);return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}@Override public void setPlacedBy(Level l,BlockPos p,BlockState s,@Nullable LivingEntity e,ItemStack stack){super.setPlacedBy(l,p,s,e,stack);if(l.getBlockEntity(p)instanceof SeasoningBottleBlockEntity b)b.loadFrom(stack);}@Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player player){if(!l.isClientSide&&l.getBlockEntity(p)instanceof SeasoningBottleBlockEntity b){ItemStack out=new ItemStack(b.ingredients().isEmpty()?ModItems.EMPTY_SEASONING_BOTTLE.get():(b.hasBase()?ModItems.PENDING_SEASONING.get():ModItems.EMPTY_SEASONING_BOTTLE.get()));SeasoningData.set(out,b.ingredients());Block.popResource(l,p,out);if(!b.ingredients().isEmpty()&&!b.hasBase())player.displayClientMessage(Component.translatable("message.kaleidoscope_grilling.missing_base_seasoning"),false);}return super.playerWillDestroy(l,p,s,player);}}
